# Generated by DesignForge. Regenerate from the workspace brief.
from html import escape
import streamlit as st

def hero(workspace):
    st.html(
        '<header class="forge-workspace-header">'
        + ('<div class="forge-orbit" aria-hidden="true"><i></i><i></i><i></i></div>' if workspace["composition"] == "ember-assistant" else '')
        + '<span class="forge-kicker">PaperPilot AI</span>'
        f'<h1>{escape(workspace["title"])}</h1>'
        f'<p>{escape(workspace["intro"])}</p>'
        '</header>'
    )

def workspace_controls(paper, model, filename, max_chars, actions):
    with st.container(key="forge-composer"):
        with st.form("ask", clear_on_submit=True):
            user_input = st.text_input(
                "Ask about your paper", max_chars=max_chars,
                placeholder="What is the paper’s main contribution?",
            )
            if paper:
                st.caption(f"{filename} · {paper.page_count} pages")
            else:
                st.caption("Add a PDF or open the FAIR sample from the sidebar to start.")
            submitted = st.form_submit_button("Send request", disabled=not paper or not model, type="primary")
    selected = None
    with st.container(key="forge-actions"):
        for column, (intent, (label, prompt)) in zip(st.columns(4), actions.items(), strict=True):
            if column.button(label, disabled=not paper or not model, width="stretch"):
                selected = (intent, prompt)
    with st.expander("Slide and viva settings"):
        left, middle, right = st.columns(3)
        slides = left.number_input("Slides", 5, 10, 6)
        questions = middle.number_input("Viva questions", 1, 15, 10)
        difficulty = right.selectbox("Viva difficulty", ["mixed", "easy", "intermediate", "advanced"])
        st.caption("Settings apply to quick actions. Include preferred counts or difficulty in custom requests.")
    if selected:
        intent, prompt = selected
        return prompt, False, {
            "intent": intent, "scope": "broad", "revision": False, "slide_count": slides,
            "question_count": questions, "difficulty": difficulty,
            "reason": "Selected quick action", "clarification": "",
        }
    return user_input if submitted else "", submitted, None

def workspace_results(history, actions, render, filename):
    with st.container(key="forge-results"):
        tabs = st.tabs(["Summary", "Concepts", "Slides", "Viva"])
        for tab, intent in zip(tabs, actions, strict=True):
            with tab:
                matching = [(pos, turn) for pos, turn in enumerate(history) if turn.intent == intent and turn.answer]
                if matching:
                    position, turn = matching[-1]
                    render(turn, position, filename)
                else:
                    st.caption(f"Use {actions[intent][0]} or submit a related request to populate this view.")
